<script setup lang="ts">import {ref,computed} from 'vue';import {Search} from 'lucide-vue-next';import {products} from '../data';import ProductCard from '../components/ProductCard.vue';import PageHero from '../components/PageHero.vue';const q=ref('');const result=computed(()=>q.value.trim()?products.filter(p=>(p.name+p.nameAr+p.description).toLowerCase().includes(q.value.toLowerCase())):products.slice(0,4));</script><template><PageHero eyebrow="Find Your Favorite" title="Search One Bite" subtitle="Search cakes, pastries, gifts and seasonal creations."/><section class="section"><div class="container"><div class="big-search"><Search/><input v-model="q" autofocus placeholder="What are you craving?"></div><h2 class="search-title">{{q?`${result.length} results for “${q}”`:'Popular right now'}}</h2><div class="product-grid"><ProductCard v-for="p in result" :key="p.id" :product="p"/></div></div></section></template>
